@block TorqueDriveA begin
    @ports p::Power{Rotation}, [frame = "arm"]
    @parameters tau::Real = 1.0, [unit = "N*m", description = "Independent torque A"]
    @equations p.e ~ tau
    @causality p => (:effort_out, :fixed)
end

@block TorqueDriveB begin
    @ports p::Power{Rotation}, [frame = "arm"]
    @parameters tau::Real = 0.5, [unit = "N*m", description = "Independent torque B"]
    @equations p.e ~ tau
    @causality p => (:effort_out, :fixed)
end
